/**
 * Шрифты сайта со своего хоста (28.10.2026): пары LUXE (Cormorant Garamond и Jost), BOLD (Unbounded и Manrope),
 * CLEAN (Inter); все под лицензией SIL Open Font License 1.1 (свободно встраивать). Файлы лежат в коде рантайма (base64,
 * кириллица и латиница отдельно, браузер берёт только нужные знаки по unicode-range) и отдаются с `/_wetop/fonts/`:
 * у посетителя сайта нет запросов к Google Fonts, CSP остаётся `font-src 'self'`.
 */
export interface FontFile {
  family: string;
  weight: string;
  range: string;
  /** Короткий хэш содержимого: долгий неизменяемый кэш безопасен */
  hash: string;
  bytes: () => Uint8Array<ArrayBuffer>;
}

const b64 = (s: string) => () => Uint8Array.from(atob(s), (ch) => ch.charCodeAt(0));

export const FONT_FILES: Record<string, FontFile> = {
  'cormorant-500-cyr': { family: 'Cormorant Garamond', weight: '500', range: 'U+0301,U+0400-045F,U+0490-0491,U+04B0-04B1,U+2116', hash: 'a062b958', bytes: b64('') },
  'cormorant-500-lat': { family: 'Cormorant Garamond', weight: '500', range: 'U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD', hash: 'c20b57f6', bytes: b64('') },
  'jost-300-500-cyr': { family: 'Jost', weight: '300 500', range: 'U+0301,U+0400-045F,U+0490-0491,U+04B0-04B1,U+2116', hash: 'e31eaf5c', bytes: b64('') },
  'jost-300-500-lat': { family: 'Jost', weight: '300 500', range: 'U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD', hash: 'd3fc5b41', bytes: b64('') },
  'unbounded-600-800-cyr': { family: 'Unbounded', weight: '600 800', range: 'U+0301,U+0400-045F,U+0490-0491,U+04B0-04B1,U+2116', hash: 'f4b8aa63', bytes: b64('') },
  'unbounded-600-800-lat': { family: 'Unbounded', weight: '600 800', range: 'U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD', hash: '1924221f', bytes: b64('') },
  'manrope-400-800-cyr': { family: 'Manrope', weight: '400 800', range: 'U+0301,U+0400-045F,U+0490-0491,U+04B0-04B1,U+2116', hash: '626cc9ca', bytes: b64('') },
  'manrope-400-800-lat': { family: 'Manrope', weight: '400 800', range: 'U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD', hash: '498cf824', bytes: b64('') },
  'inter-400-700-cyr': { family: 'Inter', weight: '400 700', range: 'U+0301,U+0400-045F,U+0490-0491,U+04B0-04B1,U+2116', hash: '9f73b2f4', bytes: b64('') },
  'inter-400-700-lat': { family: 'Inter', weight: '400 700', range: 'U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD', hash: 'f11d729b', bytes: b64('') },
};

export const FONTS_PREFIX = '/_wetop/fonts/';
export const fontPath = (key: string) => `${FONTS_PREFIX}${key}-${FONT_FILES[key]!.hash}.woff2`;

/** Файл шрифта по пути запроса или `null` */
export function fontByPath(pathname: string): FontFile | null {
  if (!pathname.startsWith(FONTS_PREFIX)) return null;
  for (const key of Object.keys(FONT_FILES)) if (fontPath(key) === pathname) return FONT_FILES[key]!;
  return null;
}

/** `@font-face` всех файлов; `swap`: текст виден сразу системным шрифтом, потом подменяется */
export function siteFontsCss(): string {
  return Object.keys(FONT_FILES)
    .map((key) => {
      const f = FONT_FILES[key]!;
      return `@font-face{font-family:'${f.family}';font-style:normal;font-weight:${f.weight};font-display:swap;src:url(${fontPath(key)}) format('woff2');unicode-range:${f.range}}`;
    })
    .join('\n');
}
